code.python:
class Solution:
    def findLocker(self, lockers: List[int], target: int) -> int:
        lo, hi = 0, len(lockers) - 1
        while lo <= hi:
            mid = (lo + hi) // 2
            if lockers[mid] == target:
                return mid
            if lockers[mid] < target:
                lo = mid + 1
            else:
                hi = mid - 1
        return -1

