class Solution {
    public int findLocker(int[] lockers, int target) {
        int lo = 0, hi = lockers.length - 1;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (lockers[mid] == target) return mid;
            if (lockers[mid] < target) lo = mid + 1;
            else hi = mid - 1;
        }
        return -1;
    }
}

